-- 1) Jalankan file ini di Supabase SQL Editor.
-- 2) Ganti ADMIN_EMAIL_HERE dengan satu email yang boleh mengakses dashboard.

create table if not exists public.weekly_monitoring (
  id bigint generated by default as identity primary key,
  week_no int not null unique check (week_no between 1 and 13),
  phase text not null,
  period text not null,
  focus text not null,
  program text,
  pic text not null,
  output text not null,
  deadline text not null,
  rag text not null default 'green' check (rag in ('green','yellow','red')),
  progress int not null default 0 check (progress between 0 and 100),
  blocker text default '',
  decision_needed text default '',
  follow_up text default '',
  updated_at timestamptz not null default now()
);

alter table public.weekly_monitoring enable row level security;
drop policy if exists "single-admin-select" on public.weekly_monitoring;
drop policy if exists "single-admin-update" on public.weekly_monitoring;
create policy "single-admin-select" on public.weekly_monitoring for select to authenticated
using ((auth.jwt() ->> 'email') = 'ADMIN_EMAIL_HERE');
create policy "single-admin-update" on public.weekly_monitoring for update to authenticated
using ((auth.jwt() ->> 'email') = 'ADMIN_EMAIL_HERE')
with check ((auth.jwt() ->> 'email') = 'ADMIN_EMAIL_HERE');

